package ruby

import (
	_ "embed"
	"strings"
)

// stdlib.txt is generated by //gazelle/ruby:stdlib_dump under the pinned Ruby.
//
//go:embed stdlib.txt
var stdlibText string

// otherPlatformStdlib lists features missing from the Linux dump.
var otherPlatformStdlib = []string{"win32/registry", "win32/resolv", "win32ole", "fiddle/win32"}

var stdlibSet = func() map[string]struct{} {
	set := make(map[string]struct{})
	for _, line := range strings.Split(stdlibText, "\n") {
		if line = strings.TrimSpace(line); line != "" {
			set[line] = struct{}{}
		}
	}
	for _, name := range otherPlatformStdlib {
		set[name] = struct{}{}
	}
	return set
}()

// IsStdLib reports whether spec names a feature shipped with Ruby itself.
func IsStdLib(spec string) bool {
	_, ok := stdlibSet[spec]
	return ok
}
